DROP PROCEDURE IF EXISTS usp_genbusinesscfgsplittable;

DELIMITER //
CREATE PROCEDURE usp_genbusinesscfgsplittable(strOriTableName VARCHAR(20), iGroupID INT, iSplitTabNO INT)
BEGIN
DECLARE tablename VARCHAR(40);
DECLARE indexname VARCHAR(40);
DECLARE pkname VARCHAR(40);
SET tablename = CONCAT(strOriTableName, '_g', iGroupID, '_s', iSplitTabNO);
SET indexname = CONCAT('ix', SUBSTRING(tablename,2), '_lstid');
SET pkname = CONCAT('pk', SUBSTRING(tablename,2), '_id');

SET @sqltext = CONCAT('DROP TABLE IF EXISTS ', tablename);
     PREPARE sqlstr FROM @sqltext;
     EXECUTE sqlstr;
SET @sqltext = CONCAT('CREATE TABLE ', tablename, '  ENGINE=InnoDB SELECT * FROM ', strOriTableName, ' WHERE 1 = 0');
     PREPARE sqlstr FROM @sqltext;
     EXECUTE sqlstr;
SET  @sqltext:=CONCAT('ALTER TABLE ', tablename, ' ADD CONSTRAINT ', pkname, ' PRIMARY KEY (cobjectid,cfunctionid)');
     PREPARE sqlstr FROM @sqltext;
     EXECUTE sqlstr;
SET  @sqltext:=CONCAT('CREATE INDEX ', indexname, ' ON ', tablename, ' (cneid)');
     PREPARE sqlstr FROM @sqltext;
     EXECUTE sqlstr;
END
//

DELIMITER ;

